import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')
API_SECRET = os.environ.get('API_SECRET', 'changeme')

def get_db():
    return psycopg2.connect(
        host=DB_HOST, database=DB_NAME,
        user=DB_USER, password=DB_PASS
    )

def verify_hmac(payload, signature):
    """Verify request signature for internal service calls"""
    expected = hmac.new(API_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports flexible filtering."""
    username = request.args.get('username', '')
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    page = request.args.get('page', '1')

    # Input length validation
    if len(username) > 100 or len(department) > 100 or len(role) > 50:
        return jsonify({'error': 'Input too long'}), 400

    # Basic character filtering - block obvious attacks
    blocked_chars = [';', '--', '/*', '*/', 'xp_', 'exec', 'execute']
    for param in [username, department, role]:
        for blocked in blocked_chars:
            if blocked.lower() in param.lower():
                return jsonify({'error': 'Invalid characters'}), 400

    conn = get_db()
    cur = conn.cursor()

    # Build dynamic query based on provided filters
    base_query = "SELECT id, username, email, department, role FROM users WHERE active = true"
    conditions = []

    if username:
        conditions.append(f" AND username ILIKE '%{username}%'")
    if department:
        conditions.append(f" AND department = '{department}'")
    if role:
        conditions.append(f" AND role = '{role}'")

    query = base_query + ''.join(conditions) + f" ORDER BY username LIMIT 50 OFFSET {(int(page)-1)*50}"

    try:
        cur.execute(query)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'username': row[1],
                'email': row[2],
                'department': row[3],
                'role': row[4]
            })
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Search failed'}), 500
    finally:
        cur.close()
        conn.close()

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, username, email, department, role FROM users WHERE id = %s", (user_id,))
    row = cur.fetchone()
    cur.close()
    conn.close()
    if row:
        return jsonify({'id': row[0], 'username': row[1], 'email': row[2], 'department': row[3], 'role': row[4]})
    return jsonify({'error': 'Not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
